ementById('invVolume').innerHTML=volume.toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})+' <small>m³</small>';document.getElementById('invPieces').textContent=pieces;document.getElementById('invTypes').textContent=types;}inputs.forEach(x=>x.addEventListener('input',calc));calc();})();</script><?php bottom();
